import pandas as pd,numpy as np
from pathlib import Path
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
cut=pd.Timestamp('2032-03-17')
D={s:pd.read_csv(Path('../persistent/stock_data')/(s+'.csv'),parse_dates=['date']).set_index('date')['close'].sort_index() for s in U}
p=pd.concat(D,axis=1).sort_index().loc[:cut]
lr=np.log(p).diff(); r10=lr.rolling(10).sum(); m=r10.mean(1); disp=r10.std(1)
vol=lr.rolling(20).std()*np.sqrt(20)
# cross-asset-relative 10d reversal, risk normalized, activated by unusually high dispersion
f=(-(r10.sub(m,axis=0))).div(vol).where(disp>disp.rolling(60).median()).shift(1)
R=np.log(p.shift(-10)/p)
A=[]
for dt in f.index:
 z=pd.concat([f.loc[dt],R.loc[dt]],axis=1).dropna()
 if len(z)>=8:A.append((dt,z.iloc[:,0].corr(z.iloc[:,1]),len(z)))
